(()=>{const P=window.PANDALS,pre=document.querySelector('main').dataset.prefix,read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{status('Changes last for this visit; device storage is unavailable.')}},status=t=>document.getElementById('page-status').textContent=t,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let saved=read('jnp26_saved',[]),visited=read('jnp26_visited',[]),route=read('jnp26_route',[]).filter(id=>P.some(p=>p.id===id));document.body.classList.toggle('dark',read('jnp26_dark',false));
function labels(){document.querySelectorAll('[data-save]').forEach(b=>{b.textContent=saved.includes(b.dataset.save)?'Saved ✓':'Save pandal';b.setAttribute('aria-pressed',saved.includes(b.dataset.save))});document.querySelectorAll('[data-visit]').forEach(b=>{b.textContent=visited.includes(b.dataset.visit)?'Visited ✓':'Mark visited';b.setAttribute('aria-pressed',visited.includes(b.dataset.visit))});document.querySelectorAll('[data-add]').forEach(b=>b.textContent=route.includes(b.dataset.add)?'In your route ✓':'Add to my route')}
function renderRoute(){const box=document.getElementById('route-stops');if(!box)return;box.innerHTML=route.length?route.map((id,i)=>{let p=P.find(p=>p.id===id);return `<article class="routestop"><div><span class="eyebrow">STOP ${i+1} · ${esc(p.area)}</span><h3><a href="${pre}pandals/${esc(id)}/index.html">${esc(p.name)}</a></h3><p>${esc(p.address)}</p></div><div class="contactlinks"><button data-up="${esc(id)}" ${i===0?'disabled':''}>↑ Earlier</button><button data-down="${esc(id)}" ${i===route.length-1?'disabled':''}>↓ Later</button><button data-remove="${esc(id)}">Remove</button></div></article>`}).join(''):`<p class="notice">Your route is empty. <a href="${pre}index.html">Explore the 117 pandals</a> and add your first stop.</p>`;let groups=[];for(let i=0;i<route.length;i+=3){let group=route.slice(i,i+4);if(group.length===1&&i>0)break;groups.push(group)}document.getElementById('route-links').innerHTML=groups.map((g,i)=>{let stops=g.map(id=>P.find(p=>p.id===id).address),u=new URL('https://www.google.com/maps/dir/');u.searchParams.set('api','1');u.searchParams.set('destination',stops.at(-1));u.searchParams.set('travelmode',document.getElementById('travel').value);if(stops.length>1){u.searchParams.set('origin',stops[0]);if(stops.length>2)u.searchParams.set('waypoints',stops.slice(1,-1).join('|'))}return `<a class="btn primary" href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">Open route ${groups.length>1?i+1:''} in Maps ↗</a>`}).join('')}
const toggle=(arr,id)=>arr.includes(id)?arr.filter(x=>x!==id):[...arr,id];document.addEventListener('click',async ev=>{let b=ev.target.closest('button');if(!b)return;let d=b.dataset;if(d.save){saved=toggle(saved,d.save);write('jnp26_saved',saved);labels()}if(d.visit){visited=toggle(visited,d.visit);write('jnp26_visited',visited);labels()}if(d.add){if(!route.includes(d.add))route.push(d.add);write('jnp26_route',route);labels();status('Added to My route.')}if(d.remove||d.up||d.down){let id=d.remove||d.up||d.down,i=route.indexOf(id);if(d.remove)route.splice(i,1);else{let j=i+(d.up?-1:1);if(j>=0&&j<route.length)[route[i],route[j]]=[route[j],route[i]]}write('jnp26_route',route);renderRoute()}if(d.share){let p=P.find(p=>p.id===d.share),text=`${p.name}\n${p.address}\nAagman: ${p.aagmanDate}\nAarti: ${p.aartiTime}\n${p.maps}`;try{if(navigator.share)await navigator.share({title:p.name,text,...(location.protocol!=='file:'?{url:location.href}:{})});else if(navigator.clipboard){await navigator.clipboard.writeText(text);status('Pandal details copied.')}else status(text)}catch{status('Sharing cancelled or unavailable.')}}if(b.id==='toggle-theme'){let dark=document.body.classList.toggle('dark');write('jnp26_dark',dark)}if(b.id==='add-saved'){route=[...new Set([...route,...saved])];write('jnp26_route',route);renderRoute()}});document.getElementById('travel')?.addEventListener('change',renderRoute);labels();renderRoute();if(location.protocol==='https:'&&'serviceWorker'in navigator)navigator.serviceWorker.register(pre+'sw.js').catch(()=>{});
})();
